injectCSS:
/* Elegant Glass Theme - Material Design Inspired */

/* === Base Rounded Corners === */
* {
    border-radius: 12px !important;
}

/* === Liquid Glass Panels === */
.termContainer,
.workspace,
.widget,
.sideWidget,
.topWidget,
.bottomWidget,
#terminal,
#dock,
#cluster,
#systemMonitor,
#networkMonitor,
#cpuHistory,
#diskSpace,
#processes,
#fileSystem,
#input,
#settingsContainer,
.settings-window,
.window,
.window-title,
.window-content,
.window-controls,
#cpu,
#mem,
#disk,
#network,
#processList,
#serverList,
#fileExplorer,
.list-item,
.list-item:hover,
.widget-header,
.widget-content,
.dock-item,
.dock-item:hover,
.tab,
.tab:hover,
.tab.active,
.btn,
.btn:hover,
.btn:active,
.input,
.input:hover,
.input:focus,
.select,
.select:hover,
.option,
.option:hover,
.slider,
.slider:hover,
.slider:active,
.tooltip,
.tooltip:hover,
.popup,
.popup:hover,
.menu,
.menu-item,
.menu-item:hover,
.context-menu,
.context-menu-item,
.context-menu-item:hover,
.notification,
.notification:hover,
.alert,
.alert:hover,
.card,
.card:hover,
.panel,
.panel:hover,
.badge,
.tag,
.avatar,
.avatar:hover,
.icon-btn,
.icon-btn:hover {
    border-radius: 16px !important;
    background: rgba(255, 255, 255, 0.03) !important;
    backdrop-filter: blur(20px) !important;
    -webkit-backdrop-filter: blur(20px) !important;
    border: 1px solid rgba(255, 255, 255, 0.08) !important;
    box-shadow:
        0 8px 32px rgba(0, 0, 0, 0.4),
        inset 0 1px 0 rgba(255, 255, 255, 0.1),
        inset 0 -1px 0 rgba(0, 0, 0, 0.2) !important;
}

/* === Frosted Glass Effect === */
body,
#root,
#container,
#desktop,
#main,
#workspace,
.terminal-wrapper,
.terminal-screen,
.terminal-header,
.terminal-body,
.terminal-footer {
    background:
        linear-gradient(135deg, rgba(255,255,255,0.02) 0%, transparent 50%),
        linear-gradient(225deg, rgba(255,255,255,0.01) 0%, transparent 50%),
        #0a0a0a !important;
}

/* === Sandblasted Metal Surfaces === */
#statusBar,
#titleBar,
#taskBar,
#menuBar,
#dock,
.dock-container,
.status-bar,
.title-bar,
.task-bar,
.menu-bar {
    background:
        linear-gradient(180deg,
            rgba(60, 60, 60, 0.4) 0%,
            rgba(40, 40, 40, 0.5) 50%,
            rgba(30, 30, 30, 0.6) 100%
        ) !important;
    backdrop-filter: blur(30px) saturate(180%) !important;
    -webkit-backdrop-filter: blur(30px) saturate(180%) !important;
    border: 1px solid rgba(255, 255, 255, 0.06) !important;
    box-shadow:
        0 4px 24px rgba(0, 0, 0, 0.5),
        inset 0 1px 0 rgba(255, 255, 255, 0.08),
        inset 0 -1px 0 rgba(0, 0, 0, 0.3) !important;
    border-radius: 20px !important;
}

/* === Liquid Glass Hover States === */
.widget:hover,
.dock-item:hover,
.list-item:hover,
.btn:hover,
.tab:hover,
.menu-item:hover {
    background: rgba(255, 255, 255, 0.06) !important;
    box-shadow:
        0 12px 48px rgba(0, 0, 0, 0.5),
        inset 0 1px 0 rgba(255, 255, 255, 0.15),
        inset 0 -1px 0 rgba(0, 0, 0, 0.2) !important;
    transform: translateY(-2px);
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94) !important;
}

/* === Subtle Glow on Active Elements === */
.widget.active,
.window.active,
.tab.active,
.btn:active,
.dock-item:active {
    background: rgba(255, 255, 255, 0.08) !important;
    box-shadow:
        0 8px 32px rgba(0, 0, 0, 0.4),
        0 0 20px rgba(255, 255, 255, 0.05),
        inset 0 1px 0 rgba(255, 255, 255, 0.2) !important;
}

/* === Glass Text Input Fields === */
.input,
.text-input,
.search-input,
textarea {
    background: rgba(0, 0, 0, 0.4) !important;
    border: 1px solid rgba(255, 255, 255, 0.1) !important;
    border-radius: 12px !important;
    color: #ffffff !important;
    box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.3) !important;
}

.input:focus,
.text-input:focus,
.search-input:focus,
textarea:focus {
    background: rgba(0, 0, 0, 0.5) !important;
    border: 1px solid rgba(255, 255, 255, 0.2) !important;
    box-shadow:
        inset 0 2px 4px rgba(0, 0, 0, 0.3),
        0 0 0 2px rgba(255, 255, 255, 0.1) !important;
    outline: none !important;
}

/* === Terminal Specific Glass === */
#terminal,
.terminal,
.xterm,
.xterm-screen {
    background: rgba(10, 10, 10, 0.95) !important;
    border-radius: 16px !important;
    box-shadow:
        0 8px 32px rgba(0, 0, 0, 0.6),
        inset 0 0 80px rgba(255, 255, 255, 0.02) !important;
}

/* === Scrollbar Styling === */
::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.2) !important;
    border-radius: 4px !important;
}

::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.15) !important;
    border-radius: 4px !important;
}

::-webkit-scrollbar-thumb:hover {
    background: rgba(255, 255, 255, 0.25) !important;
}

/* === Subtle Animations === */
@keyframes glassPulse {
    0%, 100% {
        box-shadow:
            0 8px 32px rgba(0, 0, 0, 0.4),
            inset 0 1px 0 rgba(255, 255, 255, 0.1);
    }
    50% {
        box-shadow:
            0 8px 32px rgba(0, 0, 0, 0.5),
            inset 0 1px 0 rgba(255, 255, 255, 0.15);
    }
}

@keyframes shimmer {
    0% {
        background-position: -200% 0;
    }
    100% {
        background-position: 200% 0;
    }
}

/* === Override bright colors to stay monochrome === */
.color_red,
.color_green,
.color_yellow,
.color_blue,
.color_magenta,
.color_cyan {
    filter: grayscale(100%) brightness(0.9) !important;
}

/* === Reduce neon glow from base theme === */
* {
    text-shadow: none !important;
    box-shadow: none !important;
}

/* === Keep subtle borders === */
.widget,
.window,
.panel {
    outline: 1px solid rgba(255, 255, 255, 0.05) !important;
}
